import unittest
from exactsample import philox4x32, uniform


class PhiloxKnownAnswers(unittest.TestCase):
    def test_random123_known_answers(self):
        # Independent published KATs, not values generated by this repository.
        # https://github.com/DEShawResearch/random123/blob/main/tests/kat_vectors
        cases = [
            ((0, 0, 0, 0), (0, 0), (0x6627e8d5, 0xe169c58d, 0xbc57ac4c, 0x9b00dbd8)),
            ((0xffffffff,) * 4, (0xffffffff,) * 2,
             (0x408f276d, 0x41c83b0e, 0xa20bc7c6, 0x6d5451fd)),
            ((0x243f6a88, 0x85a308d3, 0x13198a2e, 0x03707344), (0xa4093822, 0x299f31d0),
             (0xd16cfe09, 0x94fdcceb, 0x5001e420, 0x24126ea1))]
        for counter, key, expected in cases:
            self.assertEqual(tuple(philox4x32(counter, key)), expected)

    def test_open_interval_and_token_lane_addressing(self):
        expected = (0x6627e8d5, 0xe169c58d, 0xbc57ac4c, 0x9b00dbd8)
        for token, word in enumerate(expected):
            actual = uniform(0, 0, 0, 0, token)
            self.assertEqual(actual, (word + .5) / 4294967296)
            self.assertGreater(actual, 0)
            self.assertLess(actual, 1)
